const src = ($json && $json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const mail = String(src.mail || '').trim();
const inviter = String(src.inviterFirstName || '').trim();
const resultUrl = String(src.resultUrl || '#').trim();
const imageUrl = String(src.imageUrl || '').trim();
const isEn = /^en/i.test(String(src.locale || '')) || /english|anglais/i.test(String(src.langue || ''));
const btn = 'display:inline-block;background:#2E1560;color:#ffffff;text-decoration:none;font-weight:600;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;';
const link = 'color:#2E1560;text-decoration:underline;font-size:14px;';
const subject = isEn ? 'Your astral alchemy is ready ✨' : 'Votre alchimie astrale est prête ✨';
const titleFr = inviter ? ('L’alchimie que ' + inviter + ' a lancée avec vous est prête ✨') : 'Votre alchimie astrale est prête ✨';
const titleEn = inviter ? ('The alchemy ' + inviter + ' started with you is ready ✨') : 'Your astral alchemy is ready ✨';
const leadFr = 'Voici votre tableau, axe par axe.';
const leadEn = 'Here is your dashboard, axis by axis.';
const upTitleFr = 'À vous de jouer';
const upTitleEn = 'Your turn';
const upTextFr = 'Ouvrez votre espace Spikka gratuit : lancez vos propres alchimies avec qui vous voulez, et commandez vos lectures — synastrie, thème natal, prévisions — pour vous et vos proches.';
const upTextEn = 'Open your free Spikka space: run your own alchemies with whoever you like, and order your readings — synastry, birth chart, forecasts — for you and your loved ones.';
const ctaFr = 'Débloquer l’analyse détaillée';
const ctaEn = 'Unlock the detailed analysis';
const seeFr = 'Revoir le résultat en ligne';
const seeEn = 'View the result online';
const greet = isEn ? 'Hi,' : 'Bonjour,';
const title = isEn ? titleEn : titleFr;
const lead = isEn ? leadEn : leadFr;
const upTitle = isEn ? upTitleEn : upTitleFr;
const upText = isEn ? upTextEn : upTextFr;
const cta = isEn ? ctaEn : ctaFr;
const see = isEn ? seeEn : seeFr;
const imgBlock = imageUrl ? ('<p style="margin:0 0 22px;"><img src="' + imageUrl + '" alt="" style="display:block;width:100%;max-width:520px;height:auto;border-radius:14px;" /></p>') : '';
const html = '<div style="max-width:520px;margin:0 auto;padding:32px 24px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1a1a2e;">' + '<p style="font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:#2E1560;font-weight:700;margin:0 0 18px;">SPIKKA Connect</p>' + '<p style="font-size:16px;line-height:1.6;margin:0 0 12px;">' + greet + '</p>' + '<p style="font-size:18px;font-weight:700;line-height:1.4;margin:0 0 16px;">' + title + '</p>' + '<p style="font-size:16px;line-height:1.6;margin:0 0 22px;">' + lead + '</p>' + imgBlock + '<p style="margin:0 0 4px;"><a href="' + resultUrl + '" style="' + link + '">' + see + '</a></p>' + '<div style="border-top:1px solid #eceaf2;margin:26px 0 0;"></div>' + '<p style="font-size:15px;font-weight:700;color:#2E1560;margin:24px 0 8px;">' + upTitle + '</p>' + '<p style="font-size:15px;line-height:1.6;margin:0 0 22px;">' + upText + '</p>' + '<p style="margin:0;"><a href="https://spikka.io" style="' + btn + '">' + cta + '</a></p>' + '</div>';
const ccMail = String(src.inviterEmail || '').trim();
const out = { mail: mail, emailSubject: subject, emailHtml: html };
if (ccMail) out.ccMail = ccMail;
return [{ json: out }];
